const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-72.5, -13.0, -68.5, -10.5]); // Madre de Dios region, Peru

  // 2. Data Acquisition - Hansen Global Forest Change
  const hansen = ee.Image('UMD/hansen/global_forest_change_2022_v1_10');

  // Extract bands
  const treeCover = hansen.select('treecover2000');
  const loss = hansen.select('loss');
  const lossYear = hansen.select('lossyear');
  const gain = hansen.select('gain');

  // Create forest cover for 2013 (treecover2000 minus losses 2001-2013 plus gains)
  const loss2013 = loss.updateMask(lossYear.lte(13)); // lossyear 1-13 = 2001-2013
  const forest2013 = treeCover.updateMask(loss2013.neq(1)).add(gain);

  // Create forest cover for 2018 (treecover2000 minus losses 2001-2018 plus gains)
  const loss2018 = loss.updateMask(lossYear.lte(18)); // lossyear 1-18 = 2001-2018
  const forest2018 = treeCover.updateMask(loss2018.neq(1)).add(gain);

  // 3. Calculate forest cover statistics
  const stats2013 = forest2013.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2018 = forest2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  // Get pixel counts to check for valid data
  const count2013 = forest2013.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('treecover2000');

  const count2018 = forest2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('treecover2000');

  const forest2013_mean = stats2013.get('treecover2000');
  const forest2018_mean = stats2018.get('treecover2000');
  const count2013_val = count2013.getInfo();
  const count2018_val = count2018.getInfo();

  // 4. Validation & Final Answer
  console.log(`2013 Forest Cover: ${forest2013_mean.getInfo().toFixed(2)}%, Pixels: ${count2013_val}`);
  console.log(`2018 Forest Cover: ${forest2018_mean.getInfo().toFixed(2)}%, Pixels: ${count2018_val}`);

  // Check for valid data
  if (count2013_val === 0 || count2018_val === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  const cover2013 = forest2013_mean.getInfo();
  const cover2018 = forest2018_mean.getInfo();

  if (cover2013 === null || cover2018 === null || isNaN(cover2013) || isNaN(cover2018)) {
    console.log("<answer>C3</answer>");
  } else if (cover2018 < cover2013) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
